/**
 * The Module Library: browses all 35 real course modules (2 tracks, 10
 * phases) plus 8 prerequisites. Every module shows its real source files,
 * its real DECISIONS.md reasoning, and verified doc links — generated by
 * scripts/generate-library.mjs, never hand-transcribed.
 */
import { LIBRARY_MODULES, LIBRARY_PREREQUISITES, DESIGN_SYSTEM_CSS, type LibModule, type LibPrereq } from './library.generated';

/** Wraps a tutorial.html fragment (no <html>/<head>/<body> of its own,
 * just a per-page <style> accent override + content) with the course's
 * real shared stylesheet, so it renders exactly as authored inside a
 * sandboxed iframe — the actual tutorial, not a re-derived summary. */
function buildTutorialSrcdoc(fragment: string): string {
  return `<!DOCTYPE html><html><head><meta charset="utf-8"><style>${DESIGN_SYSTEM_CSS}</style></head><body>${fragment}</body></html>`;
}

function esc(s: string): string {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

/** Minimal markdown-lite: paragraphs, "- " lists, **bold**, `code`. */
function mdLite(text: string): string {
  const lines = text.trim().split('\n');
  const html: string[] = [];
  let buf: string[] = [];
  let mode: 'p' | 'ul' | null = null;

  const inline = (s: string) =>
    esc(s)
      .replace(/`([^`]+)`/g, '<code>$1</code>')
      .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');

  function flush() {
    if (buf.length === 0) return;
    if (mode === 'ul') html.push('<ul>' + buf.map((l) => `<li>${inline(l)}</li>`).join('') + '</ul>');
    else if (mode === 'p') html.push(`<p>${buf.map(inline).join(' ')}</p>`);
    buf = [];
    mode = null;
  }

  for (const raw of lines) {
    const line = raw.trim();
    if (!line) {
      flush();
      continue;
    }
    if (line.startsWith('- ')) {
      if (mode !== 'ul') flush();
      mode = 'ul';
      buf.push(line.slice(2));
    } else {
      if (mode !== 'p') flush();
      mode = 'p';
      buf.push(line);
    }
  }
  flush();
  return html.join('\n');
}

type Selection = { kind: 'module'; num: number } | { kind: 'prereq'; id: string };
type LibTab = 'tutorial' | 'code' | 'why' | 'docs';

let selection: Selection = { kind: 'module', num: 1 };
let activeLibTab: LibTab = 'tutorial';
let activeFile: string | null = null;
let root: HTMLElement | null = null;

const TRACKS = [
  { track: 1, label: 'Track 1 — Core Engine (OS & Process Substrate)' },
  { track: 2, label: 'Track 2 — Applied Layer (Browser Engine & Web Security)' },
];

function phasesForTrack(track: number): string[] {
  const seen = new Set<string>();
  const out: string[] = [];
  for (const m of LIBRARY_MODULES) {
    if (m.track === track && !seen.has(m.phase)) {
      seen.add(m.phase);
      out.push(m.phase);
    }
  }
  return out;
}

function findModule(num: number): LibModule | undefined {
  return LIBRARY_MODULES.find((m) => m.num === num);
}
function findPrereq(id: string): LibPrereq | undefined {
  return LIBRARY_PREREQUISITES.find((p) => p.id === id);
}

export function renderModuleLibrary(container: HTMLElement): void {
  root = container;
  container.innerHTML = `
    <div class="lib-layout">
      <div class="lib-nav" id="lib-nav"></div>
      <div class="lib-detail" id="lib-detail"></div>
    </div>
  `;
  renderNav();
  renderDetail();
}

function renderNav(): void {
  const nav = document.getElementById('lib-nav')!;
  let html = '<div class="lib-group-label">Prerequisites</div>';
  for (const p of LIBRARY_PREREQUISITES) {
    const active = selection.kind === 'prereq' && selection.id === p.id;
    html += `<button class="lib-nav-item ${active ? 'active' : ''}" data-kind="prereq" data-id="${p.id}">${esc(p.title)}</button>`;
  }
  for (const t of TRACKS) {
    html += `<div class="lib-track-label">${esc(t.label)}</div>`;
    for (const phase of phasesForTrack(t.track)) {
      html += `<div class="lib-group-label">${esc(phase)}</div>`;
      for (const m of LIBRARY_MODULES.filter((mm) => mm.phase === phase)) {
        const active = selection.kind === 'module' && selection.num === m.num;
        html += `<button class="lib-nav-item ${active ? 'active' : ''}" data-kind="module" data-num="${m.num}">
          <span class="lib-nav-num">${String(m.num).padStart(2, '0')}</span>${esc(m.title)}
          ${m.hasLive ? '<span class="lib-live-dot" title="Has a live demo in the tabs above"></span>' : ''}
        </button>`;
      }
    }
  }
  nav.innerHTML = html;

  nav.querySelectorAll<HTMLButtonElement>('.lib-nav-item').forEach((btn) => {
    btn.addEventListener('click', () => {
      if (btn.dataset.kind === 'module') selection = { kind: 'module', num: Number(btn.dataset.num) };
      else selection = { kind: 'prereq', id: btn.dataset.id! };
      activeLibTab = 'tutorial';
      activeFile = null;
      renderNav();
      renderDetail();
    });
  });
}

function renderDetail(): void {
  const detail = document.getElementById('lib-detail')!;

  if (selection.kind === 'prereq') {
    const p = findPrereq(selection.id)!;
    const tabs: { id: LibTab; label: string }[] = [
      { id: 'tutorial', label: 'Tutorial' },
      { id: 'docs', label: 'Docs' },
    ];
    detail.innerHTML = `
      <div class="lib-eyebrow">Prerequisite</div>
      <h2>${esc(p.title)}</h2>
      <p class="desc">${esc(p.summary)}</p>
      <div class="tabs lib-tabs">${tabs.map((t) => `<button class="tab-btn ${t.id === activeLibTab ? 'active' : ''}" data-libtab="${t.id}">${t.label}</button>`).join('')}</div>
      <div id="lib-tab-body"></div>
    `;
    detail.querySelectorAll<HTMLButtonElement>('[data-libtab]').forEach((btn) => {
      btn.addEventListener('click', () => {
        activeLibTab = btn.dataset.libtab as LibTab;
        renderPrereqTabBody(p);
      });
    });
    renderPrereqTabBody(p);
    return;
  }

  const m = findModule(selection.num)!;
  const tabs: { id: LibTab; label: string }[] = [
    { id: 'tutorial', label: 'Tutorial' },
    { id: 'code', label: `Real Code (${m.files.length})` },
    { id: 'why', label: `Why These Decisions (${m.decisions.length})` },
    { id: 'docs', label: 'Docs' },
  ];

  detail.innerHTML = `
    <div class="lib-eyebrow">Module ${String(m.num).padStart(2, '0')} · ${esc(m.phase)}${m.hasLive ? ' · <span class="lib-has-live">has a live demo above</span>' : ''}</div>
    <h2>${esc(m.title)}</h2>
    <p class="desc">${esc(m.proves)}</p>
    ${m.depends.length ? `<div class="lib-depends">Depends on: ${m.depends.map((n) => `<a class="lib-dep-link" data-num="${n}">Module ${String(n).padStart(2, '0')}</a>`).join(', ')}</div>` : ''}
    <div class="tabs lib-tabs">${tabs.map((t) => `<button class="tab-btn ${t.id === activeLibTab ? 'active' : ''}" data-libtab="${t.id}">${t.label}</button>`).join('')}</div>
    <div id="lib-tab-body"></div>
  `;

  detail.querySelectorAll<HTMLAnchorElement>('.lib-dep-link').forEach((a) => {
    a.addEventListener('click', () => {
      selection = { kind: 'module', num: Number(a.dataset.num) };
      activeLibTab = 'tutorial';
      activeFile = null;
      renderNav();
      renderDetail();
    });
  });

  detail.querySelectorAll<HTMLButtonElement>('[data-libtab]').forEach((btn) => {
    btn.addEventListener('click', () => {
      activeLibTab = btn.dataset.libtab as LibTab;
      renderTabBody(m);
    });
  });

  renderTabBody(m);
}

function docCard(d: { title: string; description: string; url: string }): string {
  return `<div class="doc-card">
    <span class="doc-card-icon">\u{1F4C4}</span>
    <div class="doc-card-body">
      <strong>${esc(d.title)}</strong> — ${esc(d.description)}<br>
      <a href="${d.url}" target="_blank" rel="noopener noreferrer">${d.url}</a>
    </div>
  </div>`;
}

function renderPrereqTabBody(p: LibPrereq): void {
  const body = document.getElementById('lib-tab-body')!;
  if (activeLibTab === 'docs') {
    body.innerHTML = p.docs.length ? p.docs.map(docCard).join('') : '<div class="desc">No doc links recorded for this topic.</div>';
    return;
  }
  body.innerHTML = `<iframe class="lib-tutorial-frame" sandbox="allow-same-origin" srcdoc="${escAttr(buildTutorialSrcdoc(p.tutorial))}"></iframe>`;
  wireTutorialFrame(body.querySelector('iframe')!);
}

function escAttr(s: string): string {
  return s.replace(/&/g, '&amp;').replace(/"/g, '&quot;');
}

type LinkTarget = { kind: 'module'; num: number } | { kind: 'prereq'; id: string } | { kind: 'why' };

/** The real tutorial.html files link to sibling modules/prerequisites/
 * DECISIONS.md with paths like "../../phase5_networking/17_.../tutorial.html"
 * that only resolve inside the real course repo, not this deployed SPA —
 * following one for real 404s (the srcdoc iframe is same-origin with the
 * parent page here, so a relative link resolves against this site's own
 * URL, which has no such route). Match on the identifying filename/dir
 * segment instead of the exact relative path, since every tutorial links
 * at a different depth. */
function resolveInternalLink(hrefNoFragment: string): LinkTarget | null {
  if (/DECISIONS\.md$/.test(hrefNoFragment)) {
    return selection.kind === 'module' ? { kind: 'why' } : null;
  }
  const tutorialMatch = hrefNoFragment.match(/([^/]+)\/tutorial\.html$/);
  if (tutorialMatch) {
    const mod = LIBRARY_MODULES.find((m) => m.dir.split('/').pop() === tutorialMatch[1]);
    return mod ? { kind: 'module', num: mod.num } : null;
  }
  const prereqMatch = hrefNoFragment.match(/(\d+_[a-z0-9_]+)\.html$/);
  if (prereqMatch) {
    const p = LIBRARY_PREREQUISITES.find((pp) => pp.id === prereqMatch[1]);
    return p ? { kind: 'prereq', id: p.id } : null;
  }
  return null; // ROADMAP.md, the prerequisites index page, etc. — no in-app target, left inert
}

/** Real external links (http/https) get target=_blank so they open a real
 * new tab instead of hijacking the iframe. Relative links get intercepted
 * and routed to the matching module/prereq/decisions tab in this app,
 * instead of being followed for real and 404ing against this site. */
function wireTutorialFrame(iframe: HTMLIFrameElement): void {
  iframe.addEventListener('load', () => {
    const doc = iframe.contentDocument;
    if (!doc) return;
    doc.querySelectorAll<HTMLAnchorElement>('a[href]').forEach((a) => {
      const href = a.getAttribute('href') || '';
      if (/^https?:\/\//.test(href)) {
        a.target = '_blank';
        a.rel = 'noopener noreferrer';
        return;
      }
      a.addEventListener('click', (e) => {
        e.preventDefault();
        const resolved = resolveInternalLink(href.split('#')[0]);
        if (!resolved) return;
        if (resolved.kind === 'why') {
          activeLibTab = 'why';
        } else {
          selection = resolved.kind === 'module' ? { kind: 'module', num: resolved.num } : { kind: 'prereq', id: resolved.id };
          activeLibTab = 'tutorial';
          activeFile = null;
        }
        renderNav();
        renderDetail();
      });
    });
  });
}

function renderTabBody(m: LibModule): void {
  const body = document.getElementById('lib-tab-body')!;

  if (activeLibTab === 'tutorial') {
    body.innerHTML = `<iframe class="lib-tutorial-frame" sandbox="allow-same-origin" srcdoc="${escAttr(buildTutorialSrcdoc(m.tutorial))}"></iframe>`;
    wireTutorialFrame(body.querySelector('iframe')!);
    return;
  }

  if (activeLibTab === 'docs') {
    body.innerHTML = m.docs.length ? m.docs.map(docCard).join('') : '<div class="desc">No doc links recorded for this phase.</div>';
    return;
  }

  if (activeLibTab === 'why') {
    body.innerHTML = m.decisions.length
      ? m.decisions.map((d) => `<div class="lib-decision-card"><div class="lib-decision-title">${esc(d.title)}</div><div class="lib-decision-body">${mdLite(d.body)}</div></div>`).join('')
      : '<div class="desc">No DECISIONS.md found for this module.</div>';
    return;
  }

  // code
  if (m.files.length === 0) {
    body.innerHTML = '<div class="desc">No source files found for this module.</div>';
    return;
  }
  if (!activeFile || !m.files.some((f) => f.name === activeFile)) activeFile = m.files[0].name;

  body.innerHTML = `
    <div class="lib-file-tabs">${m.files.map((f) => `<button class="lib-file-tab ${f.name === activeFile ? 'active' : ''}" data-file="${esc(f.name)}">${esc(f.name)}</button>`).join('')}</div>
    <pre class="lib-code"><code>${esc(m.files.find((f) => f.name === activeFile)!.code)}</code></pre>
  `;
  body.querySelectorAll<HTMLButtonElement>('.lib-file-tab').forEach((btn) => {
    btn.addEventListener('click', () => {
      activeFile = btn.dataset.file!;
      renderTabBody(m);
    });
  });
}

/** No-op hook kept for symmetry with the rest of the app's wireEvents()
 * naming convention — all library events are wired inline as it renders,
 * since it manages its own nav + detail state independent of the main
 * tab system. */
export function wireModuleLibrary(): void {}
